export const getDeleteLawUrl = (id: number,) => {




  return `/api/laws/${id}`
}

/**
 * @summary Delete a law (head admin only)
 */
export const deleteLaw = async (id: number, options?: Parameters<typeof customFetch>[1]): Promise<void> => {

  return customFetch<void>(getDeleteLawUrl(id),
  {
    ...options,
    method: 'DELETE'


  }
);}





export const getDeleteLawMutationOptions = <TError = ErrorType<void>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof deleteLaw>>, TError,{id: number}, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof deleteLaw>>, TError,{id: number}, TContext> => {

const mutationKey = ['deleteLaw'];
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof deleteLaw>>, {id: number}> = (props) => {
          const {id} = props ?? {};

          return  deleteLaw(id,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type DeleteLawMutationResult = NonNullable<Awaited<ReturnType<typeof deleteLaw>>>

    export type DeleteLawMutationError = ErrorType<void>

    /**
 * @summary Delete a law (head admin only)
 */
export const useDeleteLaw = <TError = ErrorType<void>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof deleteLaw>>, TError,{id: number}, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof deleteLaw>>,
        TError,
        {id: number},
        TContext
      > => {
      return useMutation(getDeleteLawMutationOptions(options));
    }

